import networkx as nx

def is_triangle_free(G):
    for i in G.nodes():
        for j in G.neighbors(i):
            for k in G.neighbors(j):
                if G.has_edge(i, k):
                    return False
    return True

def is_maximal(G):
    # A triangle-free graph is maximal if adding any edge creates a triangle.
    # This is equivalent to saying that for every pair of non-adjacent vertices (u, v),
    # there exists a vertex w such that (u, w) and (v, w) are edges.
    for i in range(12):
        for j in range(i + 1, 12):
            if not G.has_edge(i, j):
                # Check if adding (i, j) creates a triangle
                # This happens if there is a common neighbor w
                common_neighbors = list(nx.common_neighbors(G, i, j))
                if not common_neighbors:
                    return False
    return True

# The complete bipartite graph K_{6,6}
G = nx.complete_bipartite_graph(6, 6)
# The nodes are 0-5 and 6-11
# Let's check if it's triangle-free and maximal
print(f"Is triangle-free: {is_triangle_free(G)}")
print(f"Is maximal: {is_maximal(G)}")

